// Copyright (c) 2026 Roshan. All rights reserved.// Proprietary license — see LICENSE file for details.package com.roshan.persona.voice.tts/** * NOUS — Voice Persona (§7 Persona Voice Profile, Module 15 v3.0 rename). * * A voice persona is the *acoustic* identity NOUS speaks with — pitch, rate, * timber, accent. This is distinct from the Brain's persona (Module 2 — * response style, tone, vocabulary) which governs *what* NOUS says. The * Hilt wiring in Step 5.14 maps each Brain persona to a [VoicePersona]. * * ## The 9 voice personas (original names — no Marvel trademarks) * * Module 15 v3.0 renamed all Marvel-trademarked entries to original names. * The acoustic parameters (pitch, rate, accent) are preserved 1:1 — only * the names changed. This ensures backward compatibility with saved voice * prints (which reference ordinal, not name). * * | Persona   | Archetype   | Accent   | Pitch | Rate  | Use case                        | * |-----------|-------------|----------|-------|-------|---------------------------------| * | ATLAS     | Butler      | British  | 0.90  | 1.00  | Default — witty, refined        | * | NOVA      | Companion   | Irish    | 1.10  | 1.05  | Warm, energetic                 | * | ONYX      | Operator    | Cold     | 0.70  | 0.90  | Calculating, intimidating       | * | SAGE      | Mentor      | Soft     | 1.05  | 0.95  | Gentle, mentoring               | * | ECHO      | Peer        | Casual   | 1.00  | 1.05  | Friendly, peer-like             | * | VANGUARD  | Tactical    | Serious  | 0.85  | 1.00  | Mission-focused                 | * | ARIA      | Cheerleader | Cheerful | 1.15  | 1.10  | Optimistic, encouraging         | * | WRAITH    | Stealth     | Quiet    | 0.80  | 0.90  | Stealthy, low-key               | * | ZENITH    | Rescuer     | Calm     | 0.95  | 0.95  | Emergency-response, calm        | * * ## Pitch / Rate semantics * * - Pitch and rate are *multipliers* passed to [android.speech.tts.TextToSpeech] *   via `setPitch()` and `setSpeechRate()`. The TTS engine clamps to its *   supported range (typically 0.5–2.0). * - Values are deliberately subtle — a 1.15× pitch shift is noticeable but *   not cartoonish. The [Emotion] multiplier stacks on top, so ATLAS + *   HAPPY = 0.9 × 1.15 = 1.035 (still lower than NOVA's neutral 1.1). * * ## Voice cloning integration * * When the user has enrolled a voice clone (Step 5.8), the [VoicePersona] * is *ignored* — the cloned voice is used directly. The persona's pitch / * rate multipliers still apply (so the user's cloned voice can sound * "urgent" or "calm"), but the underlying acoustic identity is the user's * own voice. * * @see <a href="docs/strategy/module-15-digital-soul-strategy.md">§6 The 9 Personas & Dynamic Prosody</a> */enum class VoicePersona(    /** Display name (used in Settings → Voice → Persona). */    val displayName: String,    /** Accent / timber descriptor (informational; the TTS engine picks the closest voice). */    val accent: Accent,    /** Base pitch multiplier passed to TextToSpeech.setPitch(). */    val basePitch: Float,    /** Base speech rate multiplier passed to TextToSpeech.setSpeechRate(). */    val baseRate: Float,    /** Whether this persona is appropriate for a serious / urgent context. */    val allowsUrgent: Boolean = true,    /** Whether this persona can sound happy / cheerful. */    val allowsHappy: Boolean = true,) {    ATLAS    ("Atlas",    Accent.BRITISH,   0.90f, 1.00f),    NOVA     ("Nova",     Accent.IRISH,     1.10f, 1.05f),    ONYX     ("Onyx",     Accent.COLD,      0.70f, 0.90f, allowsHappy = false),    SAGE     ("Sage",     Accent.SOFT,      1.05f, 0.95f),    ECHO     ("Echo",     Accent.CASUAL,    1.00f, 1.05f),    VANGUARD ("Vanguard", Accent.SERIOUS,   0.85f, 1.00f, allowsHappy = false),    ARIA     ("Aria",     Accent.CHEERFUL,  1.15f, 1.10f),    WRAITH   ("Wraith",   Accent.QUIET,     0.80f, 0.90f, allowsHappy = false),    ZENITH   ("Zenith",   Accent.CALM,      0.95f, 0.95f);    init {        require(basePitch in 0.5f..2.0f) {            "$displayName basePitch $basePitch out of bounds [0.5, 2.0]"        }        require(baseRate in 0.5f..2.0f) {            "$displayName baseRate $baseRate out of bounds [0.5, 2.0]"        }    }    /**     * Whether this persona can validly express the given [emotion].     *     * Used by the [com.roshan.persona.voice.tts.ProsodyComputer] to clamp     * Brain-selected emotions to persona-appropriate ones. For example,     * ONYX + HAPPY → falls back to NEUTRAL (ONYX never sounds happy).     */    fun canExpress(emotion: Emotion): Boolean = when (emotion) {        Emotion.HAPPY -> allowsHappy        Emotion.URGENT -> allowsUrgent        else -> true    }}// ──────────────────────────────────────────────────────────────────────────/** * Accent / timber descriptor. Informational only — the TTS engine picks the * closest matching installed voice. Used in Settings UI to label personas. */enum class Accent(val displayLabel: String) {    BRITISH  ("British"),    IRISH    ("Irish"),    COLD     ("Cold"),    SOFT     ("Soft"),    CASUAL   ("Casual"),    SERIOUS  ("Serious"),    WARM     ("Warm"),    CHEERFUL ("Cheerful"),    QUIET    ("Quiet"),    CALM     ("Calm"),}